def search_period_4():
    solutions = []
    for a in range(2, 1000):
        for b in range(2, 1000):
            # a+b+840 = cd
            # c+d+840 = ab
            # We have c+d = ab-840 and cd = a+b+840
            # c and d are roots of x^2 - (ab-840)x + (a+b+840) = 0
            sum_cd = a*b - 840
            prod_cd = a + b + 840
            if sum_cd < 0: continue

            delta = sum_cd**2 - 4*prod_cd
            if delta >= 0:
                sqrt_delta = int(delta**0.5)
                if sqrt_delta**2 == delta:
                    if (sum_cd + sqrt_delta) % 2 == 0:
                        c = (sum_cd + sqrt_delta) // 2
                        d = (sum_cd - sqrt_delta) // 2
                        if c >= 2 and d >= 2:
                            # Now check the other two equations
                            # b+c = da-840
                            # d+a = bc-840
                            if b + c == d*a - 840 and d + a == b*c - 840:
                                solutions.append((a, b, c, d))
    return solutions

